     try  expectEqual(*[ 1 ] i32 ,  @TypeOf (x_array_ptr));

     // Coerce to many-item pointer: const  x_many_ptr: [*] i32  = x_array_ptr;
     try  expectEqual( 1234 , x_many_ptr[ 0 ]);
