    _ = &start;  // suppress 'var is never mutated' error const  slice = array[start.. 4 ];
     try  expectEqual( 2 , slice.len);

     try  expectEqual( 4 , array[ 3 ]);
    slice[ 1 ] +=  1 ;
     try  expectEqual( 5 , array[ 3 ]);
}
