     // Other than being available to call with dot syntax, struct methods are // not special. You can reference them as any other declaration inside // the struct: try  expectEqual( 0.0 , Vec3.dot(v1, v2));
}

 // Structs can have declarations. // Structs can have 0 fields. const  Empty =  struct  {
     pub const  PI =  3.14 ;
};
