### Labeled switch §

When a switch statement is labeled, it can be referenced from a `break` or `continue` . `break` will return a value from the `switch` .

A `continue` targeting a switch must have an
operand. When executed, it will jump to the matching prong, as if the `switch` were executed again with the `continue` 's operand replacing the initial switch value.

test\_switch\_continue.zig

```
const  std =  @import ( "std" );

 test "switch continue"  {
    sw:  switch  ( @as ( i32 ,  5 )) {
         5  =>  continue  :sw  4 ,

         // `continue` can occur multiple times within a single switch prong. 2 ... 4  => |v| {
             if  (v >  3 ) {
                 continue  :sw  2 ;
            }  else if  (v ==  3 ) {

                 // `break` can target labeled loops. break  :sw;
            }

             continue  :sw  1 ;
        },

         1  =>  return ,

         else  =>  unreachable ,
    }
}
``` Shell

```
$ `zig test test_switch_continue.zig` 
1/1 test_switch_continue.test.switch continue...OK
All 1 tests passed.
```

Semantically, this is equivalent to the following loop:

test\_switch\_continue\_equivalent.zig

```
const  std =  @import ( "std" );

 test "switch continue, equivalent loop"  {
     var  sw:  i32  =  5 ;
     while  ( true ) {
         switch  (sw) {
             5  => {
                sw =  4 ;
                 continue ;
            },
             2 ... 4  => |v| {
                 if  (v >  3 ) {
                    sw =  2 ;
                     continue ;
                }  else if  (v ==  3 ) {
                     break ;
                }

                sw =  1 ;
                 continue ;
            },
             1  =>  return ,
             else  =>  unreachable ,
        }
    }
}
``` Shell

```
$ `zig test test_switch_continue_equivalent.zig` 
1/1 test_switch_continue_equivalent.test.switch continue, equivalent loop...OK
All 1 tests passed.
```

This can improve clarity of (for example) state machines, where the syntax `continue :sw .next_state` is unambiguous, explicit, and immediately understandable.

However, the motivating example is a switch on each element of an array, where using a single switch can improve clarity and performance:

test\_switch\_dispatch\_loop.zig

```
const  std =  @import ( "std" );
 const  expectEqual = std.testing.expectEqual;

 const  Instruction =  enum  {
    add,
    mul,
    end,
};

 fn evaluate (initial_stack: [] const i32 , code: [] const  Instruction) ! i32  {
     var  buffer: [ 8 ] i32  =  undefined ;
     var  stack = std.ArrayList( i32 ).initBuffer(&buffer);
     try  stack.appendSliceBounded(initial_stack);
     var  ip:  usize  =  0 ;

     return  vm:  switch  (code[ip]) {
         // Because all code after `continue` is unreachable, this branch does // not provide a result. 
        .add => {
             try  stack.appendBounded(stack.pop().? + stack.pop().?);

            ip +=  1 ;
             continue  :vm code[ip];
        },
        .mul => {
             try  stack.appendBounded(stack.pop().? * stack.pop().?);

            ip +=  1 ;
             continue  :vm code[ip];
        },
        .end => stack.pop().?,
    };
}

 test "evaluate"  {
     const  result =  try  evaluate(&.{  7 ,  2 , - 3  }, &.{ .mul, .add, .end });
     try  expectEqual( 1 , result);
}
``` Shell

```
$ `zig test test_switch_dispatch_loop.zig` 
1/1 test_switch_dispatch_loop.test.evaluate...OK
All 1 tests passed.
```

If the operand to `continue` is comptime \-known, then it can be lowered to an unconditional branch
to the relevant case. Such a branch is perfectly predicted, and hence
typically very fast to execute.

If the operand is runtime-known, each `continue` can
embed a conditional branch inline (ideally through a jump table), which
allows a CPU to predict its target independently of any other prong. A
loop-based lowering would force every branch through the same dispatch
point, hindering branch prediction.

### Inline Switch Prongs §

Switch prongs can be marked as `inline` to generate
the prong's body for each possible value it could have, making the
captured value comptime .

test\_inline\_switch.zig

```
const  std =  @import ( "std" );
 const  expect = std.testing.expect;
 const  expectError = std.testing.expectError;

 fn isFieldOptional ( comptime  T:  type , field_index:  usize ) ! bool  {
     const  field_types =  @typeInfo (T).@"struct".field_types;
     return switch  (field_index) {
         // This prong is analyzed twice with `idx` being a // comptime-known value each time. inline 0 ,  1  => |idx|  @typeInfo (field_types[idx]) == .optional,
         else  =>  return error .IndexOutOfBounds,
    };
}

 const  Struct1 =  struct  { a:  u32 , b: ? u32  };

 test "using @typeInfo with runtime values"  {
     var  index:  usize  =  0 ;
     try  expect(! try  isFieldOptional(Struct1, index));
    index +=  1 ;
     try  expect( try  isFieldOptional(Struct1, index));
    index +=  1 ;
     try  expectError( error .IndexOutOfBounds, isFieldOptional(Struct1, index));
}

 // Calls to `isFieldOptional` on `Struct1` get unrolled to an equivalent // of this function: fn isFieldOptionalUnrolled (field_index:  usize ) ! bool  {
     return switch  (field_index) {
         0  =>  false ,
         1  =>  true ,
         else  =>  return error .IndexOutOfBounds,
    };
}
``` Shell

```
$ `zig test test_inline_switch.zig` 
1/1 test_inline_switch.test.using @typeInfo with runtime values...OK
All 1 tests passed.
```

The `inline` keyword may also be combined with ranges:

inline\_prong\_range.zig

```
fn isFieldOptional ( comptime  T:  type , field_index:  usize ) ! bool  {
     const  field_types =  @typeInfo (T).@"struct".field_types;
     return switch  (field_index) {
         inline 0 ...field_types.len -  1  => |idx|  @typeInfo (field_types[idx]) == .optional,
         else  =>  return error .IndexOutOfBounds,
    };
}
```

`inline else` prongs can be used as a type safe
alternative to `inline for` loops:

test\_inline\_else.zig

```
const  std =  @import ( "std" );
 const  expectEqual = std.testing.expectEqual;

 const  SliceTypeA =  extern struct  {
    len:  usize ,
    ptr: [*] u32 ,
};
 const  SliceTypeB =  extern struct  {
    ptr: [*]SliceTypeA,
    len:  usize ,
};
 const  AnySlice =  union ( enum ( u8 )) {
    a: SliceTypeA,
    b: SliceTypeB,
    c: [] const u8 ,
    d: []AnySlice,
};

 fn withFor (any: AnySlice)  usize  {
     const  Tag =  @typeInfo (AnySlice).@"union".tag_type.?;
     const  info =  @typeInfo (Tag).@"enum";
     inline for  (info.field_names, info.field_values) |field_name, field_value| {
         // With `inline for` the function gets generated as // a series of `if` statements relying on the optimizer // to convert it to a switch. if  (field_value ==  @backingInt (any)) {
             return @field (any, field_name).len;
        }
    }
     // When using `inline for` the compiler doesn't know that every // possible case has been handled requiring an explicit `unreachable`. unreachable ;
}

 fn withSwitch (any: AnySlice)  usize  {
     return switch  (any) {
         // With `inline else` the function is explicitly generated // as the desired switch and the compiler can check that // every possible case is handled. inline else  => |slice| slice.len,
    };
}

 test "inline for and inline else similarity"  {
     const  any = AnySlice{ .c =  "hello"  };
     try  expectEqual( 5 , withFor(any));
     try  expectEqual( 5 , withSwitch(any));
}
``` Shell

