test\_inline\_switch\_union\_tag.zig

```
const  std =  @import ( "std" );
 const  expectEqual = std.testing.expectEqual;

 const  U =  union ( enum ) {
    a:  u32 ,
    b:  f32 ,
};

 fn getNum (u: U)  u32  {
     switch  (u) {
         // Here `num` is a runtime-known value that is either // `u.a` or `u.b` and `tag` is `u`'s comptime-known tag value. inline else  => |num, tag| {
             if  (tag == .b) {
                 return @intFromFloat (num);
            }
             return  num;
        },
    }
}

 test "test"  {
     const  u = U{ .b =  42  };
     try  expectEqual( 42 , getNum(u));
}
