### while with Optionals §

Just like if expressions, while loops can take an optional as the
condition and capture the payload. When null is encountered the loop
exits.

When the `|x|` syntax is present on a `while` expression,
the while condition must have an Optional Type .

The `else` branch is allowed on optional iteration. In this case, it will
be executed on the first null value encountered.

test\_while\_null\_capture.zig

```
const  expectEqual =  @import ( "std" ).testing.expectEqual;

 test "while null capture"  {
     var  sum1:  u32  =  0 ;
    numbers_left =  3 ;
     while  (eventuallyNullSequence()) |value| {
        sum1 += value;
    }
     try  expectEqual( 3 , sum1);

     // null capture with an else block var  sum2:  u32  =  0 ;
    numbers_left =  3 ;
     while  (eventuallyNullSequence()) |value| {
        sum2 += value;
    }  else  {
         try  expectEqual( 3 , sum2);
    }

     // null capture with a continue expression var  i:  u32  =  0 ;
     var  sum3:  u32  =  0 ;
    numbers_left =  3 ;
     while  (eventuallyNullSequence()) |value| : (i +=  1 ) {
        sum3 += value;
    }
     try  expectEqual( 3 , i);
}

 var  numbers_left:  u32  =  undefined ;
 fn eventuallyNullSequence () ? u32  {
     return if  (numbers_left ==  0 )  null else  blk: {
        numbers_left -=  1 ;
         break  :blk numbers_left;
    };
}
``` Shell

